package io.github.diodeme.ji.relay;

import java.nio.charset.StandardCharsets;
import java.security.KeyFactory;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.security.Signature;
import java.security.spec.X509EncodedKeySpec;
import java.time.Clock;
import java.time.Duration;
import java.util.Base64;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/** One-use short-lived challenge-response authentication for trusted Relay devices. */
public final class DeviceChallengeService {
    private static final Duration CHALLENGE_TTL = Duration.ofMinutes(2);
    private final RelayMetadataStore store;
    private final Clock clock;
    private final SecureRandom random;
    private final Map<String, Challenge> challenges = new ConcurrentHashMap<>();

    public DeviceChallengeService(RelayMetadataStore store, Clock clock, SecureRandom random) {
        this.store = java.util.Objects.requireNonNull(store, "store");
        this.clock = java.util.Objects.requireNonNull(clock, "clock");
        this.random = java.util.Objects.requireNonNull(random, "random");
    }

    public IssuedChallenge issue(String tenantId, String deviceId, String connectionId) {
        RelayMetadataStore.Device device = requireActiveDevice(tenantId, deviceId);
        byte[] nonce = new byte[32];
        random.nextBytes(nonce);
        var challenge = new Challenge(tenantId, device.deviceId(), connectionId, nonce,
                clock.instant().plus(CHALLENGE_TTL));
        challenges.put(key(tenantId, deviceId, connectionId), challenge);
        return new IssuedChallenge(Base64.getUrlEncoder().withoutPadding().encodeToString(nonce),
                challenge.expiresAt());
    }

    public boolean verify(String tenantId, String deviceId, String connectionId, byte[] signature) {
        Challenge challenge = challenges.remove(key(tenantId, deviceId, connectionId));
        RelayMetadataStore.Device device = requireActiveDevice(tenantId, deviceId);
        if (challenge == null || !clock.instant().isBefore(challenge.expiresAt())) return false;
        try {
            Signature verifier = Signature.getInstance("Ed25519");
            verifier.initVerify(KeyFactory.getInstance("Ed25519").generatePublic(
                    new X509EncodedKeySpec(device.publicKey())));
            verifier.update(payload(challenge));
            return verifier.verify(signature);
        } catch (java.security.GeneralSecurityException failure) {
            return false;
        }
    }

    public static byte[] payload(String tenantId, String deviceId, String connectionId, String nonce) {
        return payload(new Challenge(tenantId, deviceId, connectionId,
                Base64.getUrlDecoder().decode(nonce), java.time.Instant.MAX));
    }

    private static byte[] payload(Challenge challenge) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            digest.update("ji-relay-device-challenge-v1\0".getBytes(StandardCharsets.UTF_8));
            digest.update(challenge.tenantId().getBytes(StandardCharsets.UTF_8));
            digest.update((byte) 0);
            digest.update(challenge.deviceId().getBytes(StandardCharsets.UTF_8));
            digest.update((byte) 0);
            digest.update(challenge.connectionId().getBytes(StandardCharsets.UTF_8));
            digest.update((byte) 0);
            digest.update(challenge.nonce());
            return digest.digest();
        } catch (java.security.NoSuchAlgorithmException impossible) {
            throw new IllegalStateException(impossible);
        }
    }

    private RelayMetadataStore.Device requireActiveDevice(String tenantId, String deviceId) {
        RelayMetadataStore.Device device = store.device(tenantId, deviceId).orElseThrow(
                () -> new SecurityException("device authentication failed"));
        if (!device.active()) throw new SecurityException("device authentication failed");
        return device;
    }

    private static String key(String tenantId, String deviceId, String connectionId) {
        return tenantId + '\0' + deviceId + '\0' + connectionId;
    }

    private record Challenge(String tenantId, String deviceId, String connectionId,
                             byte[] nonce, java.time.Instant expiresAt) {
        private Challenge {
            if (tenantId == null || tenantId.isBlank() || deviceId == null || deviceId.isBlank()
                    || connectionId == null || connectionId.isBlank() || nonce.length != 32) {
                throw new IllegalArgumentException("invalid device challenge");
            }
            nonce = nonce.clone();
        }
        @Override public byte[] nonce() { return nonce.clone(); }
    }

    public record IssuedChallenge(String nonce, java.time.Instant expiresAt) {}
}
